/*
 * Check if the data stored in the preview xbuf exceeds the maximum
 * preview size as set in the configuration, or if we are capturing
 * a preview only allow recovery from service-down. If so, set XOFF
 * flag for preview.
 */
static void
adapt_xoff_if_preview_is_full(struct hudnode *node, struct connflow *cf)
{
    struct adapt_pcb *pcb = HUDNODE_CTX(node);

    if (((pcb->ctx->working_cfg.preview_size > 0) ||
                pcb->ctx->working_cfg.f_xoff_no_preview) &&
            (pcb->ctx->xpreview.len > pcb->ctx->working_cfg.preview_size)) {
        pcb->ctx->xoff_reason |= ADAPT_XOFF_REASON_PREVIEW_FULL;
    } else {
        pcb->ctx->xoff_reason &=  ~ADAPT_XOFF_REASON_PREVIEW_FULL;
    }
    adapt_update_xoff(node, cf);
}

/* Update the statemachine state. */
static void
adapt_set_state(struct hudnode *node, struct connflow *cf,
        enum adapt_modify_state new_state)
{
    struct adapt_pcb *pcb = HUDNODE_CTX(node);

    /* Flush preview if no longer needed. */
    if (ADAPT_MODST_IS_CAPTURE_PREVIEW(pcb->ctx->state) &&
                !ADAPT_MODST_IS_CAPTURE_PREVIEW(new_state)) {
        xbuf_free(&pcb->ctx->xpreview);
        adapt_xoff_if_preview_is_full(node, cf);
    }
    ADAPT_TRACEF("node==%p old_state==%s new_state==%s\n", node,
            adapt_state_names[pcb->ctx->state], adapt_state_names[new_state]);
    pcb->ctx->state = new_state;
    if ((pcb->ctx->state == ADAPT_STATE_DONE) ||
                (pcb->ctx->state == ADAPT_STATE_FAIL)) {
        adapt_disconnect_ivs(pcb->ctx);
    }
}

