/*
 * An error has occured. Determine the proper action based on the
 * configured service-down-action value.
 */
static void
adapt_process_error(struct hudnode *node, struct connflow *cf,
        const BYTE *reason)
{
    struct adapt_pcb *pcb = HUDNODE_CTX(node);
    enum adapt_service_down_action action =
            pcb->ctx->working_cfg.service_down_action;

    ADAPT_STATS_INC(pcb->ctx, adaptation_errors);
    timer_remove(&pcb->ctx->timeout_timer);
    switch (action) {
        case ADAPT_DOWN_IGNORE:
            adapt_ivs_result_no_modification_needed(node, cf);
            break;
        case ADAPT_DOWN_RESET:
            adapt_handle_context_upper(node, pcb->ctx->above,
                    HUDEVT_ABORTED, cf, RST_WHY_CF(cf, reason));
            adapt_set_state(node, cf, ADAPT_STATE_FAIL);
            break;
        case ADAPT_DOWN_DROP:
            adapt_handle_context_upper(node, pcb->ctx->above,
                    HUDEVT_EOF, cf, NULL);
            pcb->ctx->f_eof_has_been_sent = TRUE;
            adapt_set_state(node, cf, ADAPT_STATE_DONE);
            adapt_send_closing_events_to_proxy_if_not_sent(node, cf);
            break;
    }
}

/*
 * Called if the IVS does not return a result before the configured timeout.
 * This will be treated as an error. Entrypoint to an adaptation context.
 */
static void
adapt_timeout_callback(struct timer *timer, void *arg)
{
    struct adapt_context *ctx = arg;
    struct adapt_context *saved_ctx;
    struct adapt_pcb *pcb = HUDNODE_CTX(ctx->node);

    ADAPT_TRACEF("node==%p\n", ctx->node);
    saved_ctx = adapt_dynamic_context_enter(pcb, ctx);

    ADAPTERR_IVS_TIMEOUT_LOG(CONNFLOW_FLOW_KEY(ctx->cf),
        (ctx->working_cfg.name != NULL) ?
            (const char *)ctx->working_cfg.name : "NULL",
        (ctx->working_cfg.internal_vs_name != NULL) ?
            (const char *)ctx->working_cfg.internal_vs_name : "NULL");
    ADAPT_STATS_INC(ctx, timeout_errors);
    adapt_handle_result(ctx->node, ctx->cf, ADAPT_IVS_RESULT_TIMEOUT);

    adapt_dynamic_context_exit(pcb, saved_ctx);
}

/*
 * The IVS has reported it does not need to modify the request or response,
 * send all cached headers and preview data to proxy.
 */
static void
adapt_send_preview_data_to_proxy_if_bypassing(struct hudnode *node,
        struct connflow *cf, BOOL queue_events, BOOL first_call)
{
    struct adapt_pcb *pcb = HUDNODE_CTX(node);

    /* If first call - send DONE even if there is no preview data. */
    if ((pcb->ctx->xdraining_preview.len > 0) || first_call) {
        int retry_count = ADAPT_DRAIN_PREVIEW_RETRY_COUNT;

        while ((retry_count-- > 0) && (pcb->ctx->xdraining_preview.len > 0)) {
            ADAPT_TRACEF("send data: node==%p xb==%p)\n", node,
                        &pcb->ctx->xdraining_preview);
            adapt_process_context_ingress(node, pcb->ctx->above, cf,
                        &pcb->ctx->xdraining_preview);
            /*
             * Do not free the pcb->ctx->xdraining_preview - it is now owned
             * by the filter above.
             */
        }

        /* If all preview data is sent, check if HTTP has reported _DONE. */
        if (pcb->ctx->xdraining_preview.len == 0) {
            pcb->ctx->xoff_reason &= ~(ADAPT_XOFF_REASON_IVS |
                    ADAPT_XOFF_REASON_PREVIEW_FULL);
            adapt_update_xoff(node, cf);
            if (ADAPT_MODST_IS_HTTP_DONE(pcb->ctx->state)) {
                hud_msg_t msg = HUDNODE_IS_CLIENTSIDE(node) ?
                        HUDEVT_REQUEST_DONE : HUDEVT_RESPONSE_DONE;

                ADAPT_TRACEF("sending: node==%p msg==%s(%s)\n",
                        node, hud_msg_name_str(msg), hud_msg_desc_str(msg));
                if (queue_events) {
                    adapt_handle_context_queue(node, msg, cf,
                            (void*)(UINTPTR)pcb->ctx->f_done_complete);
                } else {
                    adapt_handle_context_upper(node, pcb->ctx->above, msg, cf,
                            (void*)(UINTPTR)pcb->ctx->f_done_complete);
                }
                ADAPT_STATS_INC(pcb->ctx, records_out);
                adapt_send_closing_events_to_proxy_if_not_sent(node, cf);
            }
        }
    }
}

/*
 * Modification not needed, setup for bypass mode sending data directly
 * from HTTP to proxy.
 */
static void
adapt_ivs_result_no_modification_needed(struct hudnode *node,
        struct connflow *cf)
{
    err_t err = ERR_OK;
    struct adapt_pcb *pcb = HUDNODE_CTX(node);
    struct adapt_cfg *cfg = HUDNODE_PRIVATE(node);
    /* Save off preview data. */
    struct http_data *tmp_headers = NULL;
    xbuf_merge(&pcb->ctx->xdraining_preview, &pcb->ctx->xpreview);
    tmp_headers = pcb->ctx->original_headers;

    /*
     * Try to advance the state. If we don't have an active preview
     * (configured for no-preview, or it has been drained or dropped),
     * issue a warning about possible data loss and flip to bypass mode.
     * Should not happen as a result of normal IVS operation, but can be
     * caused by a timeout awaiting a response from the IVS, an error,
     * or the iRule "ADAPT::result bypass".
     */
    if (!ADAPT_MODST_IS_CAPTURE_PREVIEW(pcb->ctx->state)) {
        ADAPT_TRACEF("node==%p, set to bypass without or beyond preview\n",
                     node);
        ADAPTERR_BYPASS_NO_PREVIEW_LOG(CONNFLOW_FLOW_KEY(pcb->ctx->cf),
            pcb->ctx->working_cfg.name,
            (pcb->ctx->working_cfg.internal_vs_name != NULL) ?
                (const char *)pcb->ctx->working_cfg.internal_vs_name : "NULL");
    }
    adapt_advance_state(node, cf, ADAPT_STEVT_ADAPT_NO_MODIFY);
    /* If this fails, we were in a state where we could not switch to no
     * modification needed.
     */
    if (pcb->ctx->state != ADAPT_STATE_FAIL) {
        /* Send headers. */
        if (tmp_headers != NULL) {
            hud_msg_t msg = HUDNODE_IS_CLIENTSIDE(node) ? HUDEVT_REQUEST :
                        HUDEVT_RESPONSE;
            /*
             * For client side (request) adaptation only.
             * Allow PEM to inspect headers before sending them up.
             * Send HUDCTL_PERFORM_METHOD to PEM:
             *     PEM can modify headers
             *     PEM can request adapt done.
             */
            if (cfg->f_pem_exist && (msg == HUDEVT_REQUEST)) {
                err = adapt_send_request_to_pem(node, cf, tmp_headers);
                if (err == ERR_ABRT) {
                    /*
                     * ERR_ABRT code interpretation for adapt filter is
                     * discontinue the current adaptation and send
                     * response down the chain.
                     * HTTP headers already modified by PEM.
                     */
                    ADAPT_TRACEF("node==%p, send respond\n", node);
                    /* Finalize response (to nodes below, not contexts). */
                    hudQ_handle_lower(node,
                            HUDCTL_RESPONSE, cf, tmp_headers);
                    hudQ_handle_lower(node,
                            HUDCTL_RESPONSE_DONE, cf, (void *)FALSE);
                    /* Response is done - queue a close connection. */
                    adapt_advance_state(node, cf, ADAPT_STEVT_ADAPT_DONE);
                    goto out;
                }
                if (err != ERR_OK) {
                    ADAPT_TRACEF(
                        "node==%p, PEM process returned error %E(%lE)\n",
                        node, err, err);
                }
            }
            adapt_send_accepted_to_proxy_if_not_sent(node, cf);
            ADAPT_TRACEF("send header: node==%p msg==%s(%s)\n", node,
                        hud_msg_name_str(msg), hud_msg_desc_str(msg));
            adapt_handle_context_upper(node, pcb->ctx->above,
                    msg, cf, tmp_headers);
            tmp_headers = NULL;
        } else {
            adapt_send_accepted_to_proxy_if_not_sent(node, cf);
        }

        /* Send preview data. */
        adapt_send_preview_data_to_proxy_if_bypassing(node, cf, FALSE, TRUE);
    } else {
        /* Cleanup. */
        xbuf_free(&pcb->ctx->xdraining_preview);
    }
out:
    return;
}

/*
 * Cache preview data in case IVS server is down or modification is not needed.

/* Processing for result from IVS or timeout callback. */
static void
adapt_handle_result(struct hudnode *node, struct connflow *cf,
        enum ivs_result result)
{
    struct adapt_pcb *pcb = HUDNODE_CTX(node);
    ADAPT_TRACEF("node==%p, result==%d(%s)\n",
                 node, result, ivs_result_name_str(result));
    if (!ADAPT_MODST_IS_WAITING_TCL(pcb->ctx->state)) {
        pcb->ctx->result = result;

        /* If adapt is done - ignore result callbacks - most likely a close. */
        if (!ADAPT_MODST_IS_ADAPT_DONE(pcb->ctx->state) &&
                (pcb->ctx->state != ADAPT_STATE_FAIL)) {
            if (result == IVS_CONTINUE) {
                /* Continue resets timeout but does not raise a Tcl event. */
                if (ADAPT_MODST_IS_HTTP_DONE(pcb->ctx->state)) {
                    if (pcb->ctx->working_cfg.timeout > 0) {
                        timer_update(&pcb->ctx->timeout_timer,
                                (pcb->ctx->working_cfg.timeout * HZ) / 1000);
                    }
                } else {
                    /*
                     * Some ICAP servers operate in "100 continue mode"
                     * where they send 100-continue after preview and then
                     * don't begin their response until they have received
                     * the entire request. In that case a large request can
                     * trigger a timeout. Turn off the timer here and restart
                     * it after we have sent _DONE to the IVS.
                     */
                    if (pcb->ctx->working_cfg.timeout > 0) {
                        timer_remove(&pcb->ctx->timeout_timer);
                    }
                }
                adapt_advance_state(node, cf, ADAPT_STEVT_ADAPT_CONTINUE);
            } else {
                timer_remove(&pcb->ctx->timeout_timer);
                adapt_advance_state(node, cf, ADAPT_STEVT_RAISE_TCL);
                adapt_handle_result_tcl(node, cf);
            }
        }
    }
}

/*
 * Raise TCL event based on IVS result.
 * Provides an opportunity for an iRule to inspect and even change the
 * result code via the ADAPT::result Tcl command.
 */
static void
adapt_handle_result_tcl(struct hudnode *node, struct connflow *cf)
{
    struct adapt_pcb *pcb = HUDNODE_CTX(node);
    err_t err;
    tclrule_t event = HUDNODE_IS_CLIENTSIDE(node) ?
                TCLRULE_ADAPT_REQUEST_RESULT :
                TCLRULE_ADAPT_RESPONSE_RESULT;

    ADAPT_TRACEF("execute_tcl node==%p event==%s\n", node,
        tclrule_strmap[event]);

    err = tclrule_execute(node, uflow_fromconnflow(cf), event);
    ADAPT_TRACEF("... tclrule_execute() returned %E(%lE)\n", err, err);

    if (err == ERR_INPROGRESS) {
        /* Will complete asynchronously during HUDEVT_TCL. Save context. */
        ADAPTERR_IRULE_PARKED_EVENT_LOG(CONNFLOW_FLOW_KEY(cf),
                pcb->ctx->working_cfg.name, tclrule_strmap[event]);
        pcb->tcl_ctx = pcb->ctx;
    } else {
        /* Execute remaining flow even if there's a Tcl error. */
        adapt_handle_result_tcl_done(node, cf);
    }
}

/*
 * Process IVS result after TCL event has been raised. The result might
 * have been changed by the ADAPT::result Tcl command.
 */
static void
adapt_handle_result_tcl_done(struct hudnode *node, struct connflow *cf)
{
    struct adapt_pcb *pcb = HUDNODE_CTX(node);

    ADAPT_TRACEF("node==%p result==%d\n", node, pcb->ctx->result);

    /* If the event sets the state, skip. */
    switch (pcb->ctx->result) {
        case IVS_NOOP:
            adapt_ivs_clear_hudctl_queue(node);
            adapt_ivs_result_no_modification_needed(node, cf);
            pcb->ctx->xoff_reason &= ~ADAPT_XOFF_REASON_IVS;
            adapt_update_xoff(node, cf);
            break;
        case IVS_MODIFIED:
        case IVS_RESPONSE:
            /* Expect encapsulated HTTP headers from IVS. */
            if (!ADAPT_MODST_IS_ADAPT_DONE(pcb->ctx->state)) {
                adapt_advance_state(node, cf, ADAPT_STEVT_ADAPT_WAIT_HEADERS);
            }
            adapt_ivs_drain_hudctl_queue(node, cf);
            break;
        case IVS_CONTINUE:
            /* This result is handled earlier and does not raise a Tcl event. */
            DBG_ASSERT("IVS_CONTINUE does not raise a Tcl event", FALSE);
            /* fall through */
        default:
            adapt_ivs_clear_hudctl_queue(node);
            if (!ADAPT_MODST_IS_ADAPT_DONE(pcb->ctx->state))
            {
                if (pcb->ctx->result == ADAPT_IVS_RESULT_TIMEOUT) {
                    adapt_process_error(node, cf, "IVS TIMEOUT");
                    adapt_disconnect_ivs(pcb->ctx);
                } else {
                    /* Unknown or unexpected IVS result. */
                    adapt_process_error(node, cf, "Unexpected IVS result");
                    ADAPTERR_IVS_ERROR_LOG(
                        CONNFLOW_FLOW_KEY(cf),
                        (pcb->ctx->working_cfg.name != NULL) ?
                            (const char *)pcb->ctx->working_cfg.name : "NULL",
                        (pcb->ctx->working_cfg.internal_vs_name != NULL) ?
                            (const char *)pcb->ctx->working_cfg.internal_vs_name : "NULL",
                        pcb->ctx->result,
                        ivs_result_name_str(pcb->ctx->result),
                        ivs_result_desc_str(pcb->ctx->result));
                }
            }
            pcb->ctx->xoff_reason &= ~ADAPT_XOFF_REASON_IVS;
            adapt_update_xoff(node, cf);
            break;
    }
}

