/*
 * Adaptation Context. This is the complete interface to an internal virtual
 * server, including configuration parameters and execution state.
 */
struct adapt_context
{
    struct hudnode             *node;
    struct connflow            *cf;
    struct adapt_context       *above;              /* Dynamic ctx links,    */
    struct adapt_context       *below;              /*   NULL in static ctx. */
    struct ivs_connection      *ivs_connection;     /* IVS handle. */
    struct xbuf                 xpremature;         /* Ingress before req/rsp */
    struct xbuf                 xpreview;           /* Preview for bypass */
    struct xbuf                 xdraining_preview;
    struct xbuf                 xfrom_ivs_during_tcl;
    struct http_data           *original_headers;   /* Incoming HTTP headers. */
    struct timer_callback       timeout_timer;      /* IVS connection t/out. */
    struct adapt_hudctl_during_tcl hudctl_during_tcl[MAX_HUDCTL_DURING_TCL];

    /* Data from HUDEVT_ABORTED captured when f_aborted_to_be_sent was set. */
    void                       *aborted_data_to_be_sent;

    UINT32                      irid;               /* Unique ID for iRules. */

    enum adapt_modify_state     state : 8;
    enum ivs_result             result : 8;
    unsigned                    xoff_reason : 8;

    /*
     * Context is for response adaptation, operating on the serverside.
     * This supports validation of method calls on dynamic contexts,
     * even when the context is still pending and held on clientside.
     */
    BOOL                        f_for_serverside : 1;

    /*
     * The proxy has requested transfer be held. Do not receive egress
     * from IVS.
     */
    BOOL                        f_proxy_xoff : 1;

    /* XOFF has been sent to the bottom filter. */
    BOOL                        f_xoff_set : 1;

    /* Egress from IVS has been rejected (not fully consumed). */
    BOOL                        f_ivs_egress_xoff : 1;

    /* HUDEVT_*_DONE was received from below with this boolean arg value. */
    BOOL                        f_done_complete : 1;

    /*
     * HUDEVT_ACCEPTED will only be forwarded after IVS has determined if
     * modification occurs.
     */
    BOOL                        f_accepted_to_be_sent : 1;
    /*
     * HUDEVT_ABORTED will only be sent after IVS has determined if
     * modification occurs.
     */
    BOOL                        f_aborted_to_be_sent : 1;
    /*
     * HUDEVT_EOF has been received from below on serverside but is
     * deferred until after ADAPT has forwarded any IVS response payload.
     * HUDEVT_EOF can come up from SSL below on session closure, or even
     * from a lower ADAPT dynamic context on service-down-action "drop".
     */
    BOOL                        f_eof_to_be_sent : 1;
    /*
     * HUDEVT_SHUTDOWN has been received from below on serverside but is
     * deferred until after ADAPT has forwarded any IVS response payload.
     */
    BOOL                        f_shutdown_to_be_sent : 1;
    /*
     * HUDEVT_CLOSED has been received from bwlow on serverside but it
     * deferred until after ADAPT has forwarded any IVS response payload.
     */
    BOOL                        f_closed_to_be_sent : 1;
    /*
     * HUDEVT_EOF has already been sent to proxy, so don't send
     * again if received from below.    //XXX: Should this be outside context?
     */
    BOOL                        f_eof_has_been_sent : 1;

    /* Keep track of stat row handle so it can be dropped to avoid leak. */
    TMROW                       stats_row;

    /*
     * Working configuration for this context.
     * May be changed by perform-method from PEM, iRule or policy action.
