    name = c['metadata']['name']
    inventory.append({'name': name, 'kind': c['spec']['names']['kind']})
    for v in c['spec']['versions']:
        if not v.get('served'):
            continue
        schema = v.get('schema', {}).get('openAPIV3Schema', {})
